import { OrderRepository } from '../domain/OrderRepository';
import { ProductRepository } from '../domain/ProductRepository';
import { Quantity } from '../domain/Quantity';

export class CancelOrderUseCase {
  constructor(
    private orderRepository: OrderRepository,
    private productRepository: ProductRepository,
  ) {}

  execute(orderId: any): void {
    const idStr = Array.isArray(orderId) ? orderId[0] : orderId;
    const order = this.orderRepository.findById(idStr);
    if (!order) {
      throw new Error(`Order ${idStr} not found`);
    }

    if (!order.isCancellable()) {
      throw new Error(`Order ${idStr} cannot be cancelled in state ${order.getStateValue()}`);
    }

    for (const item of order.items) {
      const product = this.productRepository.findById(item.productId);
      if (product) {
        product.releaseStock(item.quantity);
      }
    }

    order.cancel();
    this.orderRepository.save(order);
  }
}

